"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { Copy, Minimize2 } from "lucide-react";
import styles from "./studio.module.css";

export type MediaPreviewKind = "image" | "video" | "model";

interface MediaPreviewModalProps {
    open: boolean;
    kind: MediaPreviewKind;
    mediaUrl?: string | null;
    mediaName?: string;
    mediaMimeType?: string;
    promptText?: string;
    thumbUrl?: string | null;
    actionHint?: string | null;
    onClose: () => void;
    onCopyPrompt?: () => void;
    onSave?: () => void;
    imageActions?: string[];
    sideActions?: string[];
    onImageAction?: (label: string) => void;
    onSideAction?: (label: string) => void;
    themeStyle?: React.CSSProperties;
}

const ACTION_ICON_MAP: Record<string, string> = {
    "再次生成": "/images/再次生成.png",
    "重新描述": "/images/重新描述.png",
    "更新描述": "/images/重新描述.png",
    "魔法改图": "/images/魔法改图.png",
    "重新改图": "/images/魔法改图.png",
    "生成视频": "/images/生成视频.png",
    "生成模型": "/images/生成模型.png",
};

function renderActionLabel(label: string) {
    const iconSrc = ACTION_ICON_MAP[label];

    return (
        <>
            {iconSrc ? <img src={iconSrc} alt="" className={styles.previewActionIcon} aria-hidden="true" /> : null}
            <span>{label}</span>
        </>
    );
}

export function MediaPreviewModal({
    open,
    kind,
    mediaUrl,
    mediaName,
    mediaMimeType,
    promptText,
    thumbUrl,
    actionHint,
    onClose,
    onCopyPrompt,
    onSave,
    imageActions = [],
    sideActions = [],
    onImageAction,
    onSideAction,
    themeStyle,
}: MediaPreviewModalProps) {
    if (!open) {
        return null;
    }

    if (typeof document === "undefined") {
        return null;
    }

    const isVideo = kind === "video" || (mediaMimeType?.startsWith("video/") ?? false);
    const isModel = kind === "model" || mediaName?.endsWith(".glb") || mediaName?.endsWith(".gltf");
    const modalActions = sideActions.length > 0 ? sideActions : imageActions;
    const hasSideActions = modalActions.length > 0 || Boolean(onSave);
    const primaryActions = modalActions.slice(0, 2);
    const secondaryActions = modalActions.slice(2);
    const [captionExpanded, setCaptionExpanded] = React.useState(false);

    const handleSideAction = (label: string) => {
        if (kind === "image") {
            onImageAction?.(label);
            return;
        }
        onSideAction?.(label);
    };

    React.useEffect(() => {
        const previousOverflow = document.documentElement.style.overflow;
        document.documentElement.style.overflow = "hidden";

        return () => {
            document.documentElement.style.overflow = previousOverflow;
        };
    }, []);

    React.useEffect(() => {
        if (!isModel) {
            return;
        }

        void import("@google/model-viewer");
    }, [isModel]);

    React.useEffect(() => {
        if (!open) {
            return;
        }

        setCaptionExpanded(false);
    }, [open, mediaUrl, promptText]);

    if (isModel) {
        return createPortal((
            <div
                className={`${styles.dialogBackdrop} ${styles.modelFullscreenBackdrop}`}
                role="dialog"
                aria-modal="true"
                onClick={(event) => {
                    if (event.target === event.currentTarget) {
                        onClose();
                    }
                }}
            >
                <div className={styles.modelFullscreenModal} style={themeStyle}>
                    <button className={styles.modelFullscreenClose} type="button" aria-label="缩小预览" onClick={onClose}>
                        <Minimize2 size={24} />
                    </button>

                    <div className={styles.modelFullscreenViewer}>
                        {mediaUrl ? (
                            // @ts-expect-error model-viewer is a Web Component
                            <model-viewer
                                src={mediaUrl}
                                alt="3D模型"
                                auto-rotate
                                camera-controls
                                style={{
                                    width: "100%",
                                    height: "100%",
                                    backgroundColor: "transparent",
                                }}
                            />
                        ) : (
                            <div className={styles.generatedArtworkLarge} />
                        )}
                    </div>

                    {modalActions.length > 0 ? (
                        <div className={styles.modelFullscreenActions}>
                            {modalActions.map((label) => (
                                <button key={label} type="button" className={styles.previewActionButton} onClick={() => handleSideAction(label)}>
                                    {renderActionLabel(label)}
                                </button>
                            ))}
                        </div>
                    ) : null}
                </div>
            </div>
        ), document.body);
    }

    return createPortal((
        <div
            className={`${styles.dialogBackdrop} ${styles.previewBackdrop}`}
            role="dialog"
            aria-modal="true"
            onClick={(event) => {
                if (event.target === event.currentTarget) {
                    onClose();
                }
            }}
        >
            <div className={styles.previewModal} data-kind={kind} data-has-actions={hasSideActions} style={themeStyle}
                onClick={(event) => { if (event.target === event.currentTarget) onClose(); }}>
                <button className={`${styles.previewClose} ${styles.previewCloseOuter}`} type="button" onClick={onClose} aria-label="关闭预览">
                    ×
                </button>

                <div className={styles.previewMain}>
                    <div
                        className={styles.previewCanvas}
                        data-kind={kind}
                    >
                        <button className={`${styles.previewClose} ${styles.previewCloseInner}`} type="button" onClick={onClose} aria-label="关闭预览">
                            ×
                        </button>

                        {mediaUrl ? (
                            isVideo ? (
                                <video src={mediaUrl} controls autoPlay muted loop className={styles.previewImage} />
                            ) : isModel ? (
                                // @ts-expect-error model-viewer is a Web Component
                                <model-viewer
                                    src={mediaUrl}
                                    alt="3D模型"
                                    auto-rotate
                                    camera-controls
                                    style={{
                                        width: "100%",
                                        height: "100%",
                                        backgroundColor: "rgba(0,0,0,0.1)",
                                    }}
                                />
                            ) : (
                                <img src={mediaUrl} alt={mediaName || "大图预览"} className={styles.previewImage} />
                            )
                        ) : (
                            <div className={styles.generatedArtworkLarge} />
                        )}
                    </div>

                    {(promptText || onCopyPrompt) ? (
                        <div
                            className={`${styles.previewCaptionBar} ${captionExpanded ? styles.previewCaptionBarExpanded : ""}`}
                            role="button"
                            tabIndex={0}
                            onClick={() => setCaptionExpanded((prev) => !prev)}
                            onKeyDown={(event) => {
                                if (event.key === "Enter" || event.key === " ") {
                                    event.preventDefault();
                                    setCaptionExpanded((prev) => !prev);
                                }
                            }}
                        >
                            {captionExpanded ? (
                                <button
                                    type="button"
                                    aria-label="收起描述"
                                    className={styles.previewCaptionCollapse}
                                    onClick={(event) => {
                                        event.stopPropagation();
                                        setCaptionExpanded(false);
                                    }}
                                >
                                    <img src="/images/Vector 967.png" alt="" aria-hidden="true" />
                                </button>
                            ) : null}

                            <div className={styles.previewCaptionLead}>
                                {thumbUrl ? (
                                    <span className={styles.previewCaptionThumbWrap} aria-hidden="true">
                                        <img src={thumbUrl} alt="" className={styles.previewCaptionThumb} />
                                    </span>
                                ) : null}
                                <span className={styles.previewCaptionText}>{promptText || "暂无描述"}</span>
                            </div>
                            <button
                                type="button"
                                className={styles.previewCaptionCopy}
                                aria-label="复制描述"
                                onClick={(event) => {
                                    event.stopPropagation();
                                    onCopyPrompt?.();
                                }}
                            >
                                <Copy size={16} />
                            </button>
                        </div>
                    ) : null}

                    {actionHint ? (
                        <p className={styles.previewHint} role="status" aria-live="polite">{actionHint}</p>
                    ) : null}
                </div>

                {hasSideActions ? (
                    <div className={styles.previewSideActions}>
                        {primaryActions.length > 0 ? (
                            <div className={styles.previewActionGroup}>
                                {primaryActions.map((label) => (
                                    <button key={label} type="button" className={styles.previewActionButton} onClick={() => handleSideAction(label)}>{renderActionLabel(label)}</button>
                                ))}
                            </div>
                        ) : null}
                        {secondaryActions.length > 0 ? (
                            <div className={styles.previewActionGroup}>
                                {secondaryActions.map((label) => (
                                    <button key={label} type="button" className={styles.previewActionButton} onClick={() => handleSideAction(label)}>{renderActionLabel(label)}</button>
                                ))}
                            </div>
                        ) : null}
                        {onSave ? <button type="button" className={`${styles.previewActionButton} ${styles.previewSaveButton}`} onClick={onSave}>储存</button> : null}
                    </div>
                ) : null}

            </div>
        </div>
    ), document.body);
}
