"use client";

import { cn } from "@/lib/utils";
import styles from "./studio.module.css";

interface PendingAssetProps {
    src: string;
    alt: string;
    className?: string;
    imageClassName?: string;
    fallbackLabel?: string;
    fit?: "contain" | "cover";
}

export function PendingAsset({
    src,
    alt,
    className,
    imageClassName,
    fit = "contain",
}: PendingAssetProps) {
    return (
        <div
            className={cn(styles.pendingAsset, className)}
            data-asset-path={src}
            data-asset-status="pending"
        >
            <img
                src={src}
                alt={alt}
                className={cn(imageClassName)}
                style={{ objectFit: fit }}
            />
        </div>
    );
}
